CREATE TABLE ads.advertisers (org_id uuid PRIMARY KEY REFERENCES identity.orgs(id), status text NOT NULL DEFAULT 'pending', contract_signed_at timestamptz, policy_accepted_at timestamptz);
CREATE TABLE ads.slots (code text PRIMARY KEY, name text NOT NULL, page text NOT NULL, format text NOT NULL, max_per_view smallint NOT NULL DEFAULT 1);
CREATE TABLE ads.campaigns (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), advertiser_org_id uuid REFERENCES identity.orgs(id), name text NOT NULL, goal text, budget_cents bigint NOT NULL, spent_cents bigint NOT NULL DEFAULT 0, pricing text NOT NULL CHECK (pricing IN ('flat','cpc','cpm')), bid_cents bigint, starts_at timestamptz, ends_at timestamptz, status text NOT NULL DEFAULT 'draft', targeting jsonb NOT NULL DEFAULT '{}');
CREATE TABLE ads.creatives (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), campaign_id uuid REFERENCES ads.campaigns(id), slot_code text REFERENCES ads.slots(code), asset_url text NOT NULL, headline text, destination_url text, claims_evidence_url text, review_status text NOT NULL DEFAULT 'pending', reviewed_by uuid, review_notes text);
CREATE TABLE ads.wallet_ledger (id bigserial PRIMARY KEY, advertiser_org_id uuid REFERENCES identity.orgs(id), kind text NOT NULL, amount_cents bigint NOT NULL, ref text, at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ads.impressions (id bigserial, creative_id uuid NOT NULL, slot_code text NOT NULL, user_hash text, at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (id, at)) PARTITION BY RANGE (at);
CREATE TABLE ads.impressions_default PARTITION OF ads.impressions DEFAULT;
CREATE TABLE ads.clicks (id bigserial PRIMARY KEY, creative_id uuid NOT NULL, user_hash text, at timestamptz NOT NULL DEFAULT now(), attributed_order_id uuid);
CREATE TABLE partners.purchase_orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), partner_org_id uuid REFERENCES identity.orgs(id), cycle_id uuid REFERENCES sales.cycles(id), kind text NOT NULL, status text NOT NULL DEFAULT 'draft', created_by uuid, approved_by uuid, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE partners.purchase_order_lines (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), purchase_order_id uuid REFERENCES partners.purchase_orders(id), variant_id uuid REFERENCES catalog.variants(id), qty numeric(12,3) NOT NULL, agreed_price_cents bigint, grade text);
CREATE TABLE partners.slots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), partner_org_id uuid REFERENCES identity.orgs(id), slot_on date NOT NULL, capacity int NOT NULL, booked int NOT NULL DEFAULT 0, halaal boolean NOT NULL DEFAULT false);
CREATE TABLE partners.documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), partner_org_id uuid REFERENCES identity.orgs(id), kind text NOT NULL, storage_url text NOT NULL, expires_on date, verified boolean NOT NULL DEFAULT false);
